_CJK = re.compile(r"[\u3400-\u9fff\uf900-\ufaff]")


def _split(text):
    """跟 `brand_names.split` 同一套(抄一份,之後那邊改了不影響這一步):中文一段、英文一段才拆,其他有中文字的算中文。"""
